import { StoryParser } from '@micromag/core';
import fieldsManager from '@micromag/fields';

// The script that generates the fields pattern of @micromag/screens at build time
import getScreenFields from '../../../../../scripts/lib/getScreenFields';

// The screens manager without that fields pattern (packages/screens/fields.js is generated by
// `npm run build` and isn't there in a fresh checkout)
import screensManager from '../../../../screens/src/defaultManager';

type FieldsPatternStrings = Record<string, string[]>;

const toRegExps = (patterns: FieldsPatternStrings): Record<string, RegExp[]> =>
    Object.keys(patterns).reduce(
        (map, type) => ({
            ...map,
            [type]: patterns[type].map((pattern) => {
                const flagsIndex = pattern.lastIndexOf('/');
                return new RegExp(pattern.slice(1, flagsIndex), pattern.slice(flagsIndex + 1));
            }),
        }),
        {},
    );

/**
 * A StoryParser set up as in the published viewer: all the screens and fields, and the fields
 * pattern that the build of @micromag/screens precomputes.
 */
export default function createViewerStoryParser() {
    const { medias, fonts } = getScreenFields() as {
        medias: FieldsPatternStrings;
        fonts: FieldsPatternStrings;
    };
    return new StoryParser({
        screensManager,
        fieldsManager,
        fieldsPattern: { medias: toRegExps(medias), fonts: toRegExps(fonts) },
    });
}
